    """The measured blocks' swap traffic in one line, recorded and not gated."""
    measured = [h for h in hosts if not h["lead_in"]]
    recorded = [h for h in measured if h["swapins_mib"] is not None and h["swapouts_mib"] is not None]
    if not recorded:
        return "not recorded"
