            f"{max(h['swapouts_mib'] for h in recorded):.1f} MiB swapped out in a measured block (vm_stat; not gated)")
    return line + (f"; not recorded in {len(measured) - len(recorded)} block(s)" if len(recorded) < len(measured) else "")

