        missing = len(measured) - len(values)
        if not values:
            return "not recorded"
        return f"up to {max(values):.{digits}f}{unit}" + (f" (not recorded in {missing} block(s))" if missing else "")
    def share(h):
        return h["unaccounted_cpu_s"] / h["cpu_capacity_s"] if h["cpu_capacity_s"] else None
    for h in measured:
